export async function bootstrapFaqSchema(): Promise<void> {
  await db.execute(
    sql`DO $$ BEGIN CREATE TYPE faq_visao AS ENUM ('contratante','empreiteiro','ambos'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;`,
  );

  await db.execute(sql`
    CREATE TABLE IF NOT EXISTS faq (
      id VARCHAR PRIMARY KEY DEFAULT gen_random_uuid(),
      question TEXT NOT NULL,
      answer TEXT NOT NULL,
      category TEXT NOT NULL,
      visao faq_visao NOT NULL DEFAULT 'ambos',
      ordem INTEGER NOT NULL DEFAULT 0,
      ativo BOOLEAN NOT NULL DEFAULT TRUE,
      criado_em TIMESTAMP NOT NULL DEFAULT NOW(),
      atualizado_em TIMESTAMP NOT NULL DEFAULT NOW()
    )
  `);

  await db.execute(sql`CREATE INDEX IF NOT EXISTS idx_faq_categoria_ordem ON faq(category, ordem)`);

  // Seed idempotente: re-execuções não duplicam nem sobrescrevem edições do admin.
  for (const item of FAQ_SEED) {
    await db.execute(sql`
      INSERT INTO faq (id, question, answer, category, visao, ordem, ativo, criado_em, atualizado_em)
      VALUES (
        ${item.id}, ${item.question}, ${item.answer}, ${item.category},
        ${item.visao}::faq_visao, ${item.ordem}, ${item.ativo},
        ${item.criadoEm}::timestamp, ${item.atualizadoEm}::timestamp
      )
      ON CONFLICT (id) DO NOTHING
    `);
  }
}
